let db,context,rows=[],currentPage='overview',toastTimer,modalCleanup,loading=false,labelObserver,stockExportPending=false;
let refreshSequence=0;
let dashboardFilters={warehouse:'',type:'',color:'',thickness_mm:'',from:'',to:''};
const chartOpen={type:true,warehouse:true,condition:true,evolution:true,purchase:true,distribution:true,variation:true};
const chartMetrics={type:'sheets',warehouse:'sheets',evolution:'sheets',distribution:'sheets'};
