function unpackBox(preselectedBox){
 if(preselectedBox&&warehouseLocked(preselectedBox.data.warehouse)){toast('Esta caixa está em um local em conferência. Conclua a conferência antes de abri-la.',true);return;}
 const eligible=currentStock(rows).boxes.filter(row=>row.data.status==='sealed'&&Number(row.data.sheets)>0&&!warehouseLocked(row.data.warehouse));
 if(!eligible.length){toast('Não há caixas fechadas disponíveis fora dos locais em conferência.',true);return;}
 modalForm('Caixa para avulsas',form=>{
  form.classList.add('unpack-form');const box=field(form,'Caixa fechada','box_id','select','',true);options(box,eligible.map(row=>[row.id,`${U.shortCode(row.data.code)} · ${boxName(row)} · ${U.catalogText(row.data.warehouse)}`]));for(const option of box.options||[]){const row=eligible.find(r=>r.id===option.value);if(row)option.title=row.data.code;}
  const quantity=field(form,'Chapas que ficarão avulsas','quantity','number','',false),damaged=field(form,'Avariadas · incluídas no total','damaged','number','',false);quantity.readOnly=true;damaged.readOnly=true;
  const balance=el('p','stock-balance-hint notice full-width');form.append(balance,notice('Toda a caixa será aberta. As chapas e avarias passam para o saldo avulso no mesmo local, sem alterar o estoque total.'));
  const reason=field(form,'Motivo / observação da abertura','reason','textarea','',true);reason.minLength=3;reason.maxLength=2000;
  function update(){const row=eligible.find(item=>item.id===box.value);quantity.value=row?row.data.sheets:'';damaged.value=row?row.data.damaged||0:'';balance.textContent=row?U.catalogText(row.data.warehouse)+' · '+num(row.data.sheets,0)+' chapas, sendo '+num(row.data.damaged||0,0)+' avariadas.':'Selecione a caixa que será aberta.';}
  box.addEventListener('change',update);if(preselectedBox&&eligible.some(row=>row.id===preselectedBox.id))box.value=preselectedBox.id;update();
  return()=>{const row=eligible.find(item=>item.id===box.value);if(!row)throw new Error('Selecione uma caixa fechada com saldo disponível.');if(warehouseLocked(row.data.warehouse))throw new Error('Este local está em conferência.');const text=reason.value.trim();if(text.length<3)throw new Error('Informe um motivo com pelo menos três caracteres.');return {box_id:row.id,reason:text};};
 },'stock_unpack');
}
